def solve(L=15.0, A=3.0, k=0.0688, h1=25.0, h2=12.0, t=8.0):
    # Falling-head permeability equation:
    # k = (a * L) / (A * t) * ln(h1 / h2)
    # Solve for standpipe area a:
    # a = (k * A * t) / (L * ln(h1 / h2))
    a = (k * A * t) / (L * math.log(h1 / h2))
    return {
        "1": {"value": a, "unit": "in.^2"}
    }

