def solve(P=5.0, x=3.0, y=4.0):
    # P in kN, x and y in m
    r = math.sqrt(x**2 + y**2)  # radial distance in m
    z_values = [0.0, 2.0, 4.0, 6.0, 10.0, 20.0]  # depths in m

    results = {}
    for i, z in enumerate(z_values, start=1):
        # Boussinesq's equation: Δσz = (3P/(2π)) * z³ / (r² + z²)^(5/2)
        numerator = 3.0 * P * z**3
        denominator = 2.0 * math.pi * (r**2 + z**2)**2.5
        delta_sigma_z = numerator / denominator  # kN/m² = kPa
        results[str(i)] = {"value": delta_sigma_z, "unit": "kPa"}

    return results

