def solve(z=4.0, q1=7.5, x1=5.0, q2=15.0, x2=10.0):
    # Boussinesq vertical stress increase due to an infinite line load
    def delta_sigma_z(q, x, z):
        return (2.0 * q * z**3) / (math.pi * (x**2 + z**2)**2)

    ds1 = delta_sigma_z(q1, x1, z)
    ds2 = delta_sigma_z(q2, x2, z)
    total = ds1 + ds2

    return {
        "1": {"value": total, "unit": "kN/m^2"}
    }

def solve(D10_mm=0.09, e=0.6):
    # Empirical correlation (Chapuis, 2004):
    # k [cm/s] = 2.4622 * [ D10^2 * e^3 / (1+e) ]^0.7825
    # where D10 is in mm.

    D10 = D10_mm  # mm, used directly in the empirical formula

    term = (D10**2) * (e**3) / (1.0 + e)
    k_cm_s = 2.4622 * (term ** 0.7825)  # cm/s

    return {
        "1": {"value": k_cm_s, "unit": "cm/s"}
    }

def solve(e_max=0.75, e_min=0.4, Gs=2.68, gamma_moist=112.0, w=0.12):
    # Unit weight of water in lb/ft^3
    gamma_w = 62.4

    # Dry unit weight
    gamma_dry = gamma_moist / (1.0 + w)

    # Void ratio in field
    # gamma_dry = Gs * gamma_w / (1 + e)
    e = (Gs * gamma_w / gamma_dry) - 1.0

    # Relative density
    Dr = (e_max - e) / (e_max - e_min)

    return {
        "1": {"value": Dr * 100.0, "unit": "%"}
    }

