def solve(k_cm_s=1.5e-3, wall_length_m=50.0, N_f=3, N_d=10, H_m=5.0):
    # Convert hydraulic conductivity from cm/s to m/s
    k_m_s = k_cm_s * 1e-2  # cm to m

    # Seepage per unit length (2D flow net): q = k * H * (N_f / N_d)
    q_per_length_m3_s = k_m_s * H_m * (N_f / N_d)  # m^3/s per meter of wall

    # Total seepage across entire wall length
    q_total_m3_s = q_per_length_m3_s * wall_length_m  # m^3/s

    # Convert to per day
    seconds_per_day = 24 * 3600
    q_total_m3_day = q_total_m3_s * seconds_per_day

    return {
        "1": {"value": q_total_m3_day, "unit": "m^3/day"}
    }

