def solve(B=4.0, q=100.0, z=1.0, x1=1.0, x2=-1.0):
    # Horizontal flexible strip load on semi-infinite soil mass
    # Delta_sigma_z = 4*b*q*x*z^2 / {pi*[(x^2 + z^2 - b^2)^2 + 4*b^2*z^2]}
    b = B / 2.0  # half-width of strip, m

    def delta_sigma_z(x):
        numerator = 4.0 * b * q * x * z**2
        denominator = math.pi * ((x**2 + z**2 - b**2)**2 + 4.0 * b**2 * z**2)
        return numerator / denominator

    ds_x1 = delta_sigma_z(x1)  # at x = +1 m
    ds_x2 = delta_sigma_z(x2)  # at x = -1 m

    return {
        "1": {"value": ds_x1, "unit": "kN/m^2"},
        "2": {"value": ds_x2, "unit": "kN/m^2"},
    }

