def solve(sigma3=140.0, delta_sigma_d_f=104.0):
    # Consolidated-drained test on normally consolidated clay -> cohesion c = 0
    # Major principal stress at failure
    sigma1 = sigma3 + delta_sigma_d_f

    # For NC clay (c=0): sin(phi) = (sigma1 - sigma3) / (sigma1 + sigma3)
    sin_phi = (sigma1 - sigma3) / (sigma1 + sigma3)
    phi = math.asin(sin_phi)  # radians

    # Failure plane angle with major principal plane
    theta = 45.0 + math.degrees(phi) / 2.0

    return {
        "1": {"value": theta, "unit": "degrees"}
    }

def solve(sigma3_eff=140.0, delta_sigma_d=104.0, sigma1_eff=244.0):
    # For CD test on NC clay, effective stresses equal total (no excess pore pressure)
    # sigma1' = sigma3' + deviator stress
    # sigma3_eff given = 140, sigma1_eff given = 244

    # The plane of maximum shear stress makes 45 degrees with principal planes.
    # Normal stress on plane of maximum shear = (sigma1' + sigma3') / 2

    sigma_n_eff = (sigma1_eff + sigma3_eff) / 2.0

    return {
        "1": {"value": sigma_n_eff, "unit": "kN/m^2"}
